"""HTML & CSS - Intermediate and Advanced sections (units 9-16).

Run exercises render in a script-less sandboxed frame (600x400) and read back text, counts,
attributes or COMPUTED CSS values, so every check here is something the browser itself reports.
"""
from .dsl import code, fill, lesson, mcq, order, run, section, t, unit

PAGE = "<!DOCTYPE html>\n<html>\n  <head>\n    <title>My page</title>\n  </head>\n  <body>\n    \n  </body>\n</html>\n"
STYLED = "<!DOCTYPE html>\n<html>\n  <head>\n    <title>My page</title>\n    <style>\n      \n    </style>\n  </head>\n  <body>\n    \n  </body>\n</html>\n"


def page(body: str, style: str = "", head: str = "") -> str:
    h = "    <title>My page</title>\n" + head + (f"    <style>\n{style}\n    </style>\n" if style else "")
    inner = "\n".join(("    " + line) if line else "" for line in body.split("\n"))
    return f"<!DOCTYPE html>\n<html>\n  <head>\n{h}  </head>\n  <body>\n{inner}\n  </body>\n</html>\n"


def styled(css: str, body: str, head: str = "") -> str:
    return page(body, "\n".join("      " + line for line in css.split("\n")), head)


def starter_with(body: str) -> str:
    """A styled starter whose body already holds the markup, so the lesson is about the CSS."""
    return styled("", body)


