    # ------------------------------------------------------------------ 16
    unit(
        "Unit 16 · Accessibility & production",
        lesson(
            "ARIA",
            "First rule of ARIA: prefer native HTML (<button>, <nav>, <dialog>) - it's accessible for free. Use ARIA to fill gaps:\n\naria-label=\"Close\"                 name for an icon-only button\naria-expanded=\"false\"              state of a disclosure/menu\naria-describedby=\"hint\"            links help text\naria-live=\"polite\"                  announce updates (toasts)\naria-hidden=\"true\"                  hide decorative icons\naria-current=\"page\"                 the active nav link",
            mcq("What's the first rule of ARIA?", ["Use native HTML elements when possible", "Use ARIA everywhere", "Hide everything", "Only use roles"], 0),
            fill("Name an icon-only button.", '<button aria-___="Close">✕</button>', "label"),
            mcq("Which attribute announces dynamic updates to screen readers?", ["aria-live", "aria-hidden", "aria-label", "role=status only"], 0),
            mcq("Mark the current page link in navigation:", ['aria-current="page"', 'aria-selected="true"', 'class="active" only', 'aria-page'], 0),
            run("Build: a menu toggle button with aria-expanded false and aria-controls menu, an icon-only close button labelled 'Close' with a decorative <span aria-hidden=\"true\">✕</span>, a nav whose second link has aria-current page, and a <div aria-live=\"polite\"> status.", "html",
                [t("expanded", selector="button[aria-controls=menu]", prop="attr:aria-expanded"), t("close label", selector="button[aria-label]", prop="attr:aria-label"),
                 t("hidden icon", selector="button[aria-label] span", prop="attr:aria-hidden"), t("current", selector="nav a:nth-of-type(2)", prop="attr:aria-current"),
                 t("live", selector="[aria-live]", prop="attr:aria-live")],
                ["false", "Close", "true", "page", "polite"],
                page('<button aria-expanded="false" aria-controls="menu">Menu</button>\n<ul id="menu" hidden><li>Item</li></ul>\n<button aria-label="Close"><span aria-hidden="true">✕</span></button>\n<nav>\n  <a href="/">Home</a>\n  <a href="/learn" aria-current="page">Learn</a>\n</nav>\n<div aria-live="polite"></div>'),
                starter=PAGE),
        ),
        lesson(
            "Accessible focus & visually-hidden text",
            "Keyboard users must see focus and reach everything:\n\n:focus-visible { outline: 3px solid var(--brand); outline-offset: 2px; }\n\nA 'skip link' jumps past navigation. Text for screen readers only uses the visually-hidden pattern (NOT display: none, which hides it from screen readers too):\n\n.sr-only {\n  position: absolute; width: 1px; height: 1px;\n  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;\n}",
            mcq("Why not use display: none for screen-reader text?", ["Screen readers ignore display: none too", "It's slow", "It's invalid", "It shows the text"], 0),
            fill("Style focus only when it should be visible (keyboard).", ":focus-___ { outline: 3px solid; }", "visible"),
            mcq("What does a skip link do?", ["Lets keyboard users jump straight to the main content", "Skips ads", "Reloads the page", "Hides the menu"], 0),
            mcq("Which contrast ratio does WCAG AA require for body text?", ["4.5:1", "2:1", "10:1", "1:1"], 0),
            run("Write the .sr-only class (position absolute, width 1px, height 1px, overflow hidden, white-space nowrap) and a :focus-visible rule with a 3px solid outline. The page has a skip link as the first element.", "html",
                [t("position", selector=".sr-only", prop="position"), t("width", selector=".sr-only", prop="width"), t("overflow", selector=".sr-only", prop="overflow"),
                 t("still displayed", selector=".sr-only", prop="display"), t("skip link first", selector="body > a:first-child", prop="attr:href")],
                ["absolute", "1px", "hidden", "block", "#main"],
                styled(".sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n}\n:focus-visible {\n  outline: 3px solid;\n}",
                       '<a href="#main">Skip to content</a>\n<nav>Menu</nav>\n<main id="main">\n  <button>Save <span class="sr-only">your profile</span></button>\n</main>'),
                starter=starter_with('<a href="#main">Skip to content</a>\n<nav>Menu</nav>\n<main id="main">\n  <button>Save <span class="sr-only">your profile</span></button>\n</main>'),
                require=[r":focus-visible"], forbid=[r"display\s*:\s*none"]),
        ),
        lesson(
            "Head, SEO & performance",
            "A production <head>:\n\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Unique, descriptive title</title>\n<meta name=\"description\" content=\"…\">\n<link rel=\"icon\" href=\"/favicon.svg\">\n<meta property=\"og:title\" content=\"…\">     <!-- link previews -->\n<link rel=\"preload\" href=\"/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n\nAlso: lazy-load offscreen images, defer scripts (<script defer>), and set lang on <html>.",
            mcq("Which meta tag controls the search-result snippet?", ['name="description"', 'name="keywords"', 'charset', 'name="robots" only'], 0),
            fill("Social link-preview title.", '<meta property="og:___" content="Codeingo">', "title"),
            mcq("What does <script defer> do?", ["Downloads in parallel and runs after the HTML is parsed", "Never runs", "Runs first", "Blocks rendering"], 0),
            mcq("Why set lang=\"en\" on <html>?", ["Screen readers and translators use it", "SEO only", "Fonts", "It's required to render"], 0),
            run("Write a full page with lang=\"en\" on <html> and a head containing meta charset utf-8, the viewport meta tag, title 'Codeingo - Learn to code', a meta description, and an og:title meta.", "html",
                [t("lang", selector="html", prop="attr:lang"), t("charset", selector="meta[charset]", prop="attr:charset"),
                 t("viewport", selector="meta[name=viewport]", prop="attr:content"), t("title", selector="title", prop="text"),
                 t("description", selector="meta[name=description]", prop="count"), t("og", selector="meta[property='og:title']", prop="count")],
                ["en", "utf-8", "width=device-width, initial-scale=1", "Codeingo - Learn to code", "1", "1"],
                '<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n    <title>Codeingo - Learn to code</title>\n    <meta name="description" content="Bite-sized coding lessons with real code.">\n    <meta property="og:title" content="Codeingo">\n  </head>\n  <body>\n    <h1>Codeingo</h1>\n  </body>\n</html>\n',
                starter=PAGE),
        ),
    ),
